declare_lint ! { #[doc = " The `confusable_idents` lint detects visually confusable pairs between"] #[doc = " identifiers."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " // Latin Capital Letter E With Caron"] #[doc = " pub const Ě: i32 = 1;"] #[doc = " // Latin Capital Letter E With Breve"] #[doc = " pub const Ĕ: i32 = 2;"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " This lint warns when different identifiers may appear visually similar,"] #[doc = " which can cause confusion."] #[doc = ""] #[doc = " The confusable detection algorithm is based on [Unicode® Technical"] #[doc = " Standard #39 Unicode Security Mechanisms Section 4 Confusable"] #[doc = " Detection][TR39Confusable]. For every distinct identifier X execute"] #[doc = " the function `skeleton(X)`. If there exist two distinct identifiers X"] #[doc = " and Y in the same crate where `skeleton(X) = skeleton(Y)` report it."] #[doc = " The compiler uses the same mechanism to check if an identifier is too"] #[doc = " similar to a keyword."] #[doc = ""] #[doc = " Note that the set of confusable characters may change over time."] #[doc = " Beware that if you \"forbid\" this lint that existing code may fail in"] #[doc = " the future."] #[doc = ""] #[doc = " [TR39Confusable]: https://www.unicode.org/reports/tr39/#Confusable_Detection"] pub CONFUSABLE_IDENTS , Warn , "detects visually confusable pairs between identifiers" , crate_level_only }